	@Test
	void publishingIsAtomicAndOldLeasesSurviveReplacementAndRollback() throws Exception {
		service = openService();
		service.publish(writeGeneration(1L, -1L, 7L, FIRST_PROBE_SHARD, 41L, true));
		FrontierStatisticsLease oldLease = service.acquire(7L);

		service.publish(writeGeneration(2L, 1L, 8L, SECOND_PROBE_SHARD, 82L, true));
		try (oldLease; FrontierStatisticsLease currentLease = service.acquire(8L)) {
			assertEquals(41L, oldLease.shard(FIRST_PROBE_SHARD).column(0).value(0L));
			assertEquals(82L, currentLease.shard(SECOND_PROBE_SHARD).column(0).value(0L));
		}

		assertTrue(service.rollback());
		assertEquals(1L, service.status().generationId());
		try (FrontierStatisticsLease rolledBack = service.acquire(7L)) {
			assertEquals(41L, rolledBack.shard(FIRST_PROBE_SHARD).column(0).value(0L));
		}
		assertFalse(service.rollback());

		service.close();
		service = openService();
		assertEquals(1L, service.status().generationId(), "rollback must durably switch CURRENT");
	}

