	@Test
	void committedMemoryTailIsQueryableBeforeDeltaPublication() throws Exception {
		service = openService();
		service.publish(writeGeneration(1L, -1L, 7L, FIRST_PROBE_SHARD, 41L, true));
		List<FrontierMutation> mutations = List.of(
				new FrontierMutation(8L, 8L, true, true, 11L, 22L, 31L, 0L),
				new FrontierMutation(9L, 9L, true, true, 12L, 22L, 32L, 0L));
		service.recordStoreCommit(9L, 9L, System.currentTimeMillis());
		service.installMutationTail(mutations);
		FrontierLeafProbe predicate = new FrontierLeafProbe(
				FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE, 0L, 22L, 0L, 0L);

		assertEquals(FrontierFallbackReason.CONFIDENCE_TOO_WIDE, service.status().fallbackReason(),
				"mapped views must not ignore the unpublished overlay");
		assertEquals(2.0d, service.estimateLeafCurrent(predicate).pointRows(), 0.0d);
		assertEquals(2.0d, service.estimateProjectedDistinctCurrent(predicate, 0), 0.0d);
		assertEquals(2.0d, service.estimateJoinCurrent(
				new FrontierJoinProbe(predicate, 0, predicate, 0)).pointRows(), 0.0d);

		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		service.publishDelta(mutations, config);

		assertEquals(FrontierFallbackReason.NONE, service.status().fallbackReason());
		assertEquals(2.0d, service.estimateLeafCurrent(predicate).pointRows(), 0.0d);
	}

	@Test
	void committedMemoryTailAppendsOnlyNewTransactionRows() throws Exception {
		service = openService();
		service.publish(writeGeneration(1L, -1L, 7L, FIRST_PROBE_SHARD, 41L, true));
		FrontierLeafProbe predicate = predicateProbe(22L);

		for (long sequence = 8L; sequence <= 10L; sequence++) {
			service.recordStoreCommit(sequence, sequence, System.currentTimeMillis());
			FrontierMutation mutation = new FrontierMutation(
					sequence, sequence, true, true, sequence + 100L, 22L, sequence + 200L, 0L);
			assertTrue(service.appendMutationTail(List.of(mutation)),
					"a contiguous transaction must extend the bounded memory tail");
		}

		assertEquals(3.0d, service.estimateLeafCurrent(predicate).pointRows(), 0.0d);
	}

